<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import type { StoryEntityView } from '../../../desktop/src/contracts/characters/types'
import { emptyWorldbookEntry, readWorldbookProfile, writeWorldbookProfile } from '../../../desktop/src/contracts/characters/worldbook'
import type { SourceCard } from '../../../desktop/src/contracts/worldbuilding/types'
import type { BookApi } from '../api/writing'
import { messageOf } from '../api/http'
import { DraftStore } from './drafts'
const props = defineProps<{ api: BookApi; owner: string }>()
const entries = ref<StoryEntityView[]>([]), sources = ref<SourceCard[]>([]), selected = ref<StoryEntityView | null>(null), error = ref(''), notice = ref(''), busy = ref(false)
const name = ref(''), kind = ref<StoryEntityView['entityType']>('character'), status = ref<StoryEntityView['status']>('candidate'), profile = ref(emptyWorldbookEntry()), aliases = ref('')
const source = reactive({ title: '', excerpt: '', userNotes: '' })
const kinds = { character: '人物', location: '地点', item: '物品', organization: '组织', world_rule: '世界规则' }
const store = new DraftStore(sessionStorage, props.owner, props.api.id)
const formValue = computed(() => ({ name: name.value, kind: kind.value, status: status.value, profile: profile.value, aliases: aliases.value, expectedUpdatedAt: selected.value?.updatedAt }))
type FormValue = typeof formValue.value
const recovery = ref<FormValue | null>(null), sourceRecovery = ref<typeof source | null>(null)
let changing = false, baseline = JSON.stringify(formValue.value)
const formKey = () => `entity:${selected.value?.id ?? 'new'}`
watch(formValue, value => { if (!changing && JSON.stringify(value) !== baseline) { try { store.write(formKey(), selected.value?.updatedAt ?? '', value) } catch { error.value = '恢复空间不足，请先保存或复制当前条目。' } } }, { deep: true, flush: 'sync' })
watch(source, value => { if (value.title || value.excerpt || value.userNotes) { try { store.write('source:new', '', value) } catch { error.value = '恢复空间不足，请先保存或复制当前资料。' } } }, { deep: true, flush: 'sync' })
function findRecovery() { baseline = JSON.stringify(formValue.value); const copy = store.read<FormValue>(formKey()); recovery.value = copy && JSON.stringify(copy.data) !== baseline ? copy.data : null }
function restore() { const value = recovery.value; if (!value) return; try {
  if (typeof value.name !== 'string' || typeof value.aliases !== 'string' || !Object.hasOwn(kinds, value.kind) || !['candidate', 'approved', 'archived'].includes(value.status)) throw new Error('恢复副本格式无效。')
  const parsed = readWorldbookProfile({ worldbook: value.profile }); if (!parsed) throw new Error('恢复副本格式无效。')
  changing = true; name.value = value.name; aliases.value = value.aliases; kind.value = value.kind; status.value = value.status; profile.value = parsed
  if (selected.value && typeof value.expectedUpdatedAt === 'string') selected.value = { ...selected.value, updatedAt: value.expectedUpdatedAt }
  recovery.value = null
} catch (e) { error.value = messageOf(e) } finally { changing = false } }
async function read() { const [a, b] = await Promise.all([props.api.entities(), props.api.sources()]); entries.value = a; sources.value = b.sources }
function fresh() { changing = true; selected.value = null; name.value = ''; kind.value = 'character'; status.value = 'candidate'; profile.value = emptyWorldbookEntry(); aliases.value = ''; notice.value = ''; findRecovery(); changing = false }
function choose(entry: StoryEntityView) { changing = true; try { const parsed = readWorldbookProfile(JSON.parse(entry.profileJson)); if (!parsed) throw new Error('此条目使用原有档案格式，请在桌面版查看和编辑，现有内容已保留。'); selected.value = entry; name.value = entry.canonicalName; kind.value = entry.entityType; status.value = entry.status; profile.value = parsed; aliases.value = parsed.aliases.join('、'); findRecovery() } catch (e) { error.value = messageOf(e) } finally { changing = false } }
async function save() { busy.value = true; error.value = ''; notice.value = ''; const previousKey = formKey(); try { profile.value.aliases = [...new Set(aliases.value.split(/[、,，\n]/).map(s => s.trim()).filter(Boolean))]; const sent = JSON.stringify(formValue.value); const result = await props.api.saveEntity({ ...(selected.value ? { id: selected.value.id, expectedUpdatedAt: selected.value.updatedAt } : {}), entityType: kind.value, canonicalName: name.value, status: status.value, profileJson: writeWorldbookProfile(selected.value?.profileJson || '{}', profile.value) }); if (sent === JSON.stringify(formValue.value)) { store.remove(previousKey); choose(result) } else { selected.value = result; store.write(formKey(), result.updatedAt, formValue.value) }; notice.value = result.status === 'approved' ? '已保存为正式设定。' : '条目已保存，尚未成为正式事实。'; await read() } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function addSource() { busy.value = true; error.value = ''; const sent = JSON.stringify(source); try { await props.api.createSource({ ...source }); if (JSON.stringify(source) === sent) { source.title = ''; source.excerpt = ''; source.userNotes = ''; store.remove('source:new') }; await read(); notice.value = '资料已保存。资料内容需要作者采用后才成为正式事实。' } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
onMounted(async () => { try { await read(); findRecovery(); const copy = store.read<typeof source>('source:new'); if (copy && ['title', 'excerpt', 'userNotes'].every(key => typeof copy.data[key as keyof typeof source] === 'string')) sourceRecovery.value = copy.data } catch (e) { error.value = messageOf(e) } })
</script>
<template><section class="world-records"><header><h2>世界书与资料</h2><p class="muted">收录人物、地点和世界规则。候选与资料不会自动成为正式设定。</p></header><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="success" role="status">{{ notice }}</p><aside v-if="recovery" class="recovery-note">此条目有未保存的恢复副本。<button @click="restore">恢复条目表单</button><button @click="recovery = null">暂不恢复</button></aside><div class="world-records-grid"><aside class="paper-card"><button :disabled="busy" @click="fresh">＋ 新建条目</button><button v-for="entry in entries" :key="entry.id" class="record-entry" :disabled="busy" @click="choose(entry)"><b>{{ entry.canonicalName }}</b><small>{{ kinds[entry.entityType] }} · {{ entry.status === 'approved' ? '正式' : entry.status === 'candidate' ? '候选' : '归档' }}</small></button><p v-if="!entries.length" class="muted">尚无世界书条目。</p></aside><form class="paper-card record-form" @submit.prevent="save"><div class="form-row"><label>条目名称<input v-model="name" required maxlength="160"></label><label>类型<select v-model="kind"><option v-for="(label, key) in kinds" :key="key" :value="key">{{ label }}</option></select></label></div><label>别名 / 称呼<input v-model="aliases" placeholder="用顿号分隔"></label><label>公开设定<textarea v-model="profile.description" rows="4" maxlength="30000"></textarea></label><label>作者备注<textarea v-model="profile.authorNotes" rows="3" maxlength="30000"></textarea></label><label class="check-label"><input v-model="profile.alwaysInclude" type="checkbox">写作上下文始终包含此条目</label><label>正式状态<select v-model="status"><option value="candidate">候选，待核对</option><option value="approved">正式，已由我确认</option><option value="archived">归档</option></select></label><button class="primary" :disabled="busy">保存世界书条目</button></form></div><details class="source-section"><summary>创作资料（{{ sources.length }}）</summary><aside v-if="sourceRecovery" class="recovery-note">有未保存的资料卡。<button @click="Object.assign(source, sourceRecovery); sourceRecovery = null">恢复资料表单</button></aside><form class="record-form paper-card" @submit.prevent="addSource"><label>资料标题<input v-model="source.title" required></label><label>资料摘录<textarea v-model="source.excerpt" rows="4" required></textarea></label><label>我的笔记<textarea v-model="source.userNotes" rows="2"></textarea></label><button :disabled="busy">保存资料卡</button></form><article v-for="item in sources" :key="item.id" class="event-card"><h3>{{ item.title }}</h3><p>{{ item.excerpt }}</p><p class="muted">{{ item.userNotes }}</p></article></details></section></template>
